(function(global){
"use strict";
function Chart(ctx,config){
  this.ctx=ctx;this.config=config;this.data=config.data;
  this.options=config.options||{};
  this._draw();
}
Chart.prototype.destroy=function(){
  if(this.ctx)this.ctx.clearRect(0,0,this.ctx.canvas.width,this.ctx.canvas.height);
};
Chart.prototype._draw=function(){
  var ctx=this.ctx,data=this.data,opts=this.options;
  if(!data||!data.labels||!data.datasets)return;
  var W=ctx.canvas.width,H=ctx.canvas.height;
  ctx.clearRect(0,0,W,H);
  var isDark=window.matchMedia('(prefers-color-scheme:dark)').matches;
  var textColor=isDark?'#fff':'#333';
  var gridColor=isDark?'#3a3a3c':'#e5e5e5';
  var labels=data.labels;
  var n=labels.length;
  var padL=50,padR=20,padT=30,padB=80;
  var chartW=W-padL-padR,chartH=H-padT-padB;
  var allVals=[];
  data.datasets.forEach(function(ds){ds.data.forEach(function(v){allVals.push(v);});});
  var maxVal=Math.max.apply(null,allVals)||1;
  ctx.strokeStyle=gridColor;ctx.lineWidth=1;
  for(var gi=0;gi<=5;gi++){
    var gy=padT+chartH-(gi/5)*chartH;
    ctx.beginPath();ctx.moveTo(padL,gy);ctx.lineTo(padL+chartW,gy);ctx.stroke();
    ctx.fillStyle=textColor;ctx.font='11px sans-serif';ctx.textAlign='right';
    ctx.fillText(Math.round((gi/5)*maxVal),padL-6,gy+4);
  }
  var groupW=chartW/n;
  var ds=data.datasets;
  var barW=groupW*0.35;
  ds.forEach(function(dataset,di){
    var offset=(di-(ds.length-1)/2)*barW;
    dataset.data.forEach(function(val,i){
      var x=padL+i*groupW+groupW/2+offset;
      var bh=(val/maxVal)*chartH;
      var y=padT+chartH-bh;
      ctx.fillStyle=dataset.backgroundColor||'#0071e3';
      ctx.beginPath();
      ctx.roundRect?ctx.roundRect(x-barW/2,y,barW,bh,4):ctx.rect(x-barW/2,y,barW,bh);
      ctx.fill();
    });
  });
  ctx.fillStyle=textColor;ctx.font='11px sans-serif';ctx.textAlign='center';
  labels.forEach(function(lbl,i){
    ctx.fillText(lbl,padL+i*groupW+groupW/2,padT+chartH+18);
  });
  var legX=padL,legY=padT-10;
  ds.forEach(function(dataset,di){
    ctx.fillStyle=dataset.backgroundColor||'#0071e3';
    ctx.fillRect(legX,legY,14,10);
    ctx.fillStyle=textColor;ctx.font='11px sans-serif';ctx.textAlign='left';
    ctx.fillText(dataset.label||'',legX+18,legY+9);
    legX+=ctx.measureText(dataset.label||'').width+40;
  });
};
global.Chart=Chart;
})(window);
